def transform(grid):
    h, w = len(grid), len(grid[0])
    # Find full-length single-color divider rows and columns.
    div_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    div_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    if div_rows and div_cols:
        r = div_rows[0]
        c = div_cols[0]
        # Use the quadrant with the most colors differing from its surrounding background.
        regions = [
            (range(0, r), range(0, c)),
            (range(0, r), range(c + 1, w)),
            (range(r + 1, h), range(0, c)),
            (range(r + 1, h), range(c + 1, w)),
        ]
        def score(region):
            rs, cs = region
            return sum(grid[i][j] != 5 for i in rs for j in cs)
        sr, sc = regions[max(range(4), key=lambda k: score(regions[k]))]
        source = [[grid[i][j] for j in sc] for i in sr]
        out = [row[:] for row in grid]
        for rs, cs in regions:
            for ii, i in enumerate(rs):
                for jj, j in enumerate(cs):
                    out[i][j] = source[ii % len(source)][jj % len(source[0])]
        return out

    # A single divider copies the pattern on one side to the other.
    if div_rows:
        r = div_rows[0]
        out = [row[:] for row in grid]
        top = [row[:] for row in grid[:r]]
        for i in range(r + 1, h):
            out[i] = top[(i - r - 1) % len(top)][:]
        return out
    if div_cols:
        c = div_cols[0]
        out = [row[:] for row in grid]
        for i in range(h):
            left = grid[i][:c]
            for j in range(c + 1, w):
                out[i][j] = left[(j - c - 1) % len(left)]
        return out
    return grid
